 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker_colors = [value for value in counts if value != background]
    if not marker_colors:
        return [row[:] for row in grid]
    marker = max(marker_colors, key=lambda value: counts[value])
    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
